---RefreshBoard
---@param goodsId number  装备道具id
---@param uid  number     装备唯一id
---@param idType  Constants.IDType     装备唯一id
function CommonTipsEquip:RefreshBoard(goodsId, uid, idType)
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    local equipConfId = idType == Constants.IDType.GoodsCommission and goodsVo.effectId or goodsId
    if idType == Constants.IDType.GoodsCommission then
        goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(equipConfId)
    end
    -- local quality = goodsVo.quality
    CommonTipsBoard.RefreshTitleNode(
            self,
            goodsVo.name,
            nil,
            nil,
            nil,
            nil,
            EquipUtils.GetEquipmentSetIcon(equipConfId)
    )

    local isCustom = idType == Constants.IDType.GoodsCommission
    local equipDojo
    if isCustom then
        equipDojo  = EquipUtils.GenerateCustomEquip(goodsId)
    else
        local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
        ---@type EquipDojo
        equipDojo = equipComp:GetEquipById(uid)
    end
    self.equipDojo  = equipDojo
    self:RefreshAttributeNodes(equipDojo, isCustom)
    self:RefreshAttrTips(equipDojo)

    CfUtils.RefeshGoodGo2(self.GoodNode, goodsId, nil, nil, nil, function()
        
    end, nil, {isTips = 1})

end

---RefreshTitleNode 根据内容刷新提示板
