---@param rare      number 稀有度
function CommonTipsBoard:RefreshTitleNode(titleText, rare, customBgColor, customTextColor, isDisableTextColor, iconPath)
    --- 刷新标题
    ---@type CommonTitleNode
    local env = CfUtils.GetLuaScr(self.TitleNode.gameObject, TitleNodePath)
