    env:RefreshUI(titleText, rare, customBgColor, customTextColor, isDisableTextColor, iconPath)
end

---RefreshAttributeNodes
---@param equipDojo EquipDojo  装备数据
---@param isCustom  boolean    是否是定制道具
function CommonTipsEquip:RefreshAttributeNodes(equipDojo, isCustom)
    CfUtils.FillImage(self.SetIcon, EquipUtils.GetEquipmentSetIcon(equipDojo.equipmentId))
    CfUtils.FillText(self.EquipmentLvNum, equipDojo.level)
    
    -- 更新主属性
    local mainAttrId, mainAttrNum = equipDojo.mainAttrId, checkNumber(equipDojo.mainAttrNum)
    local mainAttrVo = cardConfMgr:GetBasicAttrByBasicAttrAdditionId(mainAttrId)
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(mainAttrId)
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    
    CfUtils.FillText(self.MainAttrTitle, attrAdditionVo.attrAdditionName)
    CfUtils.FillImage(self.MainAttrIcon, mainAttrVo.icon)
    
    if checkInt(mainEquipAttrVo.isRandom) == 0 then
        CfUtils.FillText(self.MainAttrNum, string.format('<color=#484848>%s</color>', attribute_format(mainAttrVo.isConversion, mainAttrNum)))
        CfUtils.SetActive(self.MainAttrNumRange, false)
        CfUtils.SetActive(self.BtnExplain, false)
    else
        CfUtils.FillText(self.MainAttrNum, attribute_format(mainAttrVo.isConversion, mainAttrNum))
        CfUtils.SetUISwitchText(self.MainAttrNum, EquipUtils.GetEquipmentMainAttrQuality(equipDojo))
        local attrNum = mainEquipAttrVo.attrNum[tostring(equipVo.rare)]
        local str = string.format("(%s~%s)", attribute_format(attrAdditionVo.isConversion, attrNum.baseMin), attribute_format(attrAdditionVo.isConversion, attrNum.baseMax))
        CfUtils.FillText(self.MainAttrNumRange, str)
        CfUtils.SetActive(self.MainAttrNumRange, true)
        CfUtils.SetActive(self.BtnExplain, true)
    end

    CfUtils.SetActive(self.BtnLock, not isCustom)
    if not isCustom then
        self:RefreshLockImg(checkNumber(equipDojo.locked))
    end

    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local equipFilterVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", equipVo.suitId)
    CfUtils.FillText(self.SetDesc, equipFilterVo.desc2)

    if  EquipUtils.GetEquipmentSubAttrMaxCountByDojo(equipDojo) <= 0 then
        CfUtils.SetActive(self.SecondAttributeTitle, false)
        CfUtils.SetActive(self.ListGroup, false)
    else
        CfUtils.SetActive(self.SecondAttributeTitle, true)
        CfUtils.SetActive(self.ListGroup, true)
        local maxSubCount = EquipUtils.GetEquipmentSubAttrMaxCountByDojo(equipDojo)
        for i = 1, CardProgressionConstants.EquipmentSubAttrLimit do
            local node = self.ListGroup:GetChild(i - 1)
            local isShow = i <= maxSubCount
            CfUtils.SetActive(node, isShow)
            if isShow then
                local attrAdditionId  = checkNumber(equipDojo[string.format("attr%sId", i)])
                local attrNum         = equipDojo[string.format("attr%sNum", i)]
                local attrQuality     = equipDojo[string.format("attr%sQuality", i)]
                print("attrQuality", attrQuality, attrAdditionId)
                self:RefreshAttributeNode(node, equipDojo.equipmentId, attrAdditionId, attrNum, attrQuality, equipDojo.star, i)
            end
        end
    end


end

function CommonTipsEquip:RefreshAttributeNode(node, equipmentId, attrId, attrNum, attrQuality, star, index)
    ---@type CommonEquipAttributeNode
    local nodeEnv = CfUtils.GetLuaScr(node.gameObject, ATTRIBUTE_PATH)
    if nodeEnv == nil then return end
    nodeEnv:RefreshUI(equipmentId, attrId, attrNum, attrQuality, star, index)
end

function CommonTipsEquip:RefreshLockImg(locked)
    CfUtils.SetActive(self.ImgLock, locked == 1)
    CfUtils.SetActive(self.UnLock, locked == 0)
end

function CommonTipsEquip:RequestEquipmentLock()
    ---@type EquipDojo
    local dojo   = self.equipDojo
    local status = checkNumber(dojo.locked) == 0 and 1 or 0
    local playerEquipmentId = dojo.id
    local requestData = {status = status, playerEquipmentId = playerEquipmentId}
    GameUtils.Request(Interfaces.EquipmentLock, requestData, function(request, response)
        if checkInt(response.errCode) == 0 then
            -------------------------------------
            --- 更新全局数据
            ---@type EquipmentComponent
            local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
            equipComp:SetLockStateById(playerEquipmentId, status)
            
            -------------------------------------
            --- 更新UI
            self:RefreshLockImg(status)

            -------------------------------------
            --- 显示tips
            if checkNumber(dojo.locked) > 0 then
                GameUtils.Toast(localize("锁定成功"))
            end

            Events.Broadcast(Constants.EventNames.UICultivateEquipChangeLockStateComplete, playerEquipmentId, status, Constants.UICultivateEquipType.Equip)
        end
    end)
end

---RefreshAttrTips
---@param equipDojo EquipDojo
function CommonTipsEquip:RefreshAttrTips(equipDojo)
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrNum = mainEquipAttrVo.attrNum[tostring(goodsVo.quality)]

    CfUtils.FillText(self.TipsTextTitle, localize("主属性说明"))
    CfUtils.FillText(self.TipsTextDesc1, localize("该装备的基础属性随机出现，范围是<color=#FF1BAF>(_num1_~_num2_)</color>", {_num1_ = attribute_format(attrAddVo.isConversion, attrNum.baseMin), _num2_ = attribute_format(attrAddVo.isConversion, attrNum.baseMax)}))
    CfUtils.FillText(self.TipsTextDesc2, localize("这个范围分为6个品质，灰绿蓝紫橙红。这个品质越高，每次升级时，带来的加成越高"))
end

